
import React, { useEffect, useState } from "react";

import { KDSElement } from "external/KDSTypes";

type Props = {
    background?: React.ReactElement,
    interval?: number,
    children: React.ReactElement | ReadonlyArray<React.ReactElement>
} & KDSElement<HTMLDivElement>;

export default function KDSCarousel({
    background,
    interval,
    children,
    ref,
    style
}: Props): React.ReactElement {
    const pages = React.Children.toArray(children);

    const [currentIndex, setCurrentIndex] = useState<number>(0);
    const [isPaused, setIsPaused] = useState<boolean>(false);

    useEffect(() => {
        if (isPaused) return;

        const changeIndex = setInterval(() => {
            setCurrentIndex((prevIndex) => (prevIndex + 1) % pages.length);
        }, interval ?? 3000);

        return () => clearInterval(changeIndex);
    }, [isPaused]);

    // TODO: Make this a reusable component
    const backgroundContainer = (
        <div style={{
            display: "flex",
            alignItems: "center",
            height: "100%",
            zIndex: -10
        }}>
            {background}
        </div>);
    return (
        <div
            ref={ref}
            onMouseEnter={() => setIsPaused(true)}
            onMouseLeave={() => setIsPaused(false)}
            style={{
                // display: "flex",
                position: "relative",
                minHeight: "400",
                maxHeight: "500px",
                width: "100%",
                overflow: "hidden",
            }}>
            {backgroundContainer}
            <div
                style={{
                    display: "flex",
                    position: "absolute",
                    height: "100%",
                    width: "100%",
                    alignItems: "center",
                    alignContent: "center",
                    justifyContent: "center",
                    backgroundColor: "rgba(0, 0, 0, .3)",
                    top: 0,
                    left: 0,
                    zIndex: 0,
                    ...style
                }}>
                <div
                    style={{
                        width: "800px"
                    }}>
                    {pages[currentIndex]}
                </div>
            </div>
        </div>
    );
}
