
import React, { useRef } from "react";


import InternalKDSLayout from "internal/layout/InternalKDSLayout.react";
import { KDSElement } from "external/KDSTypes";
import useKDSHover from "external/actions/useKDSHover";

export type KDSHoverMenuItems = ReadonlyArray<React.ReactElement<typeof InternalKDSLayout>>;

type Props = {
    children: [React.ReactNode, React.ReactNode]
} & KDSElement<HTMLDivElement>;

export default function InternalKDSHoverContent({
    children,
    style,
}: Props): React.ReactElement {
    const ref = useRef<HTMLDivElement>(null);
    const isHovered = useKDSHover(ref);

    return (
        <div
            ref={ref}
            style={{
                position: "relative",
            }}>
            <div >
                {children[0]}
            </div>
            <div
                style={{
                    backgroundColor: "white",
                    borderEndStartRadius: "24px",
                    borderEndEndRadius: "24px",
                    boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.2)",
                    position: "fixed",
                    zIndex: 999, // TODO Make KDSLayer.background / KDSLayer.tooltip / etc
                    ...style,
                }}>
                {isHovered ? children[1] : null}
            </div>
        </div>
    );
}
