import React from "react";

import { KDSRoutes } from "external/router/useKDSRouter";

type Node = { [key: string]: any };

export default class RouteTrie {
    root: Node;
    routes: KDSRoutes;
    constructed: boolean;

    constructor(routes: KDSRoutes | undefined) {
        this.root = {}
        this.routes = routes ?? {};
        this.constructed = false;
    }

    __construct = (): void => {
        if (this.constructed || !this.routes) {
            return;
        }
        for (const [path, component] of Object.entries(this.routes)) {
            let node = this.root;
            const parts = this.__tokenizePath(path);
            for (const part of parts) {
                if (!node[part]) node[part] = {};
                node = node[part];
            }
            node.render = component
        }
    }

    __tokenizePath = (path: string): ReadonlyArray<string> => {
        return path.split('/').filter(Boolean);
    }

    public resolve = (path: string): React.ReactElement | null => {
        this.__construct();
        const parts = this.__tokenizePath(path);
        let wildcard = null;
        let node = this.root;
        for (let i = 0; i < parts.length; i++) {
            const part = parts[i];
            if (!(part in node)) {
                return (node["*"] ?? wildcard ?? null)?.render();
            }
            if ("*" in node) {
                wildcard = node["*"];
            }
            node = node[part];
        }
        return "render" in node ? node.render() : wildcard?.render();
    }
}