
import { KDSState } from "external/KDSTypes";
import { useContext } from "react";
import { AppContext } from "internal/app_context";
import { KDSTheme } from "external/theme/KDSTheme";

export default function useKDSTheme(): KDSState<KDSTheme> {
    const { theme, setTheme } = useContext(AppContext);
    return [theme, setTheme];
}