
import React from "react";

type Props = {
    children?: React.ReactNode,
    gridRowStart?: "auto" | (string & {}) | (number & {}),
    gridRowEnd?: "auto" | (string & {}) | (number & {}),
    gridColumnStart?: "auto" | (string & {}) | (number & {}),
    gridColumnEnd?: "auto" | (string & {}) | (number & {}),
    gridArea?: "auto" | (string & {}) | (number & {}),
    justifySelf?: 'start' | 'end' | 'center' | 'stretch',
    alignSelf?: 'start' | 'end' | 'center' | 'stretch',

    style?: {} // Temporary for debugging purposes only
}

export default function KDSGridItem(
    {
        children,
        gridRowStart,
        gridRowEnd,
        gridColumnStart,
        gridColumnEnd,
        gridArea,
        justifySelf,
        alignSelf, style }: Props): React.ReactElement {
    return (
        <div style={
            {
                gridRowStart,
                gridRowEnd,
                gridColumnStart,
                gridColumnEnd,
                gridArea,
                justifySelf,
                alignSelf,
                overflow: 'hidden',
                ...style,
            }}>
            {children}
        </div>
    );
}

