import InternalKDSText from "internal/text/InternalKDSText.react";
import React from "react";

type Props = {
    title: string
};

export default function KDSTitleText({
    title
}: Props): React.ReactElement {
    return (
        <InternalKDSText
            size="large"
            weight="bold"
        >
            {title}
        </InternalKDSText>
    );
}

