
import React from "react";
import useKDSTheme from "external/theme/useKDSTheme";

type Props = {
    icon: string,
    color: 'primary' | 'active' | 'disabled' | 'negative', // TODO make use a KDSIconColor type
    size?: 'small' | 'default' | 'large' | 'x-large', // 18, 24, 36 or 48
    type?: 'outlined' | 'filled' | 'round' | 'sharp',
    svg?: string,
    ico?: string, // TODO make icon svg or ico be different option
}

export type KDSIconProps = Props;
/*
https://fonts.google.com/icons?icon.set=Material+Symbols
*/
export default function KDSIcon({ icon, color, size, type, svg, ico }: Props): React.ReactElement {
    const [theme] = useKDSTheme();
    const pixelSize = size === 'small' ? '18px' : size === 'large' ? '36px' : size === 'x-large' ? '48px' : '24px';
    const iconColor = theme.icon[color];
    if (svg != null) {
        return (
            <svg style={{
                height: pixelSize,
                width: pixelSize,
                fill: iconColor,
                userSelect: 'none',
            }}>
                <use xlinkHref={svg} />
            </svg>);
    }
    if (ico != null) {
        return (<img src={ico} alt="Icon" height={pixelSize} />);
    }
    const materialType = (type ?? 'filled') === 'filled'
        ? '-outlined'
        : `-${type}`;
    return (
        <>
            <i
                aria-label={`Material Icon: ${icon}`}
                style={
                    {
                        fontSize: pixelSize,
                        color: iconColor,
                        userSelect: 'none',
                        width: pixelSize,
                    }}
                className={`material-symbols${materialType}`}
            >
                {icon}
            </i >
        </>
    );
}
