
import { KDSSetState } from "external/KDSTypes";
import React, { useContext } from "react";

type KDSRouter = {
    path: string,
    goToRoute: (path: string, replace?: boolean) => void,
    setHash: (hash: string) => void,
    base: string,
    host: string,
}

export default function useKDSRouter(): KDSRouter {
    const { base, path, setPath } = useContext(RouterContext);
    const goToRoute = (path: string, replace: boolean = false) => {
        const uri = path.startsWith("/") ? path : (base + path).replace("//", "/"); // TODO make this more robust and in a common js folder for url combine
        if (replace && window?.history?.replaceState) {
            window.history.replaceState(window.history.state, document.title, uri);
        } else if (!replace && window?.history?.pushState && window.location.pathname + window.location.search !== uri) {
            window.history.pushState(window.history.state, document.title, uri);
        } else {
            window.location.assign(uri);
        }
        setPath(uri);
    };
    const setHash = (hash: string) => {
        window.location.hash = `#${hash}`;
    };
    return {
        path: path.length > 0 ? path : window.location.pathname.replace(base, "/"),
        goToRoute,
        setHash,
        base,
        host: window.location.host,
    };
}

export type KDSRoutes = {
    [key: string]: React.ElementType | (() => React.ReactElement);
};
export type RouteConfig = {
    base: string,
    path: string,
    setPath: KDSSetState<string>,
};
export const RouterContext = React.createContext<RouteConfig>({
    base: "/",
    path: "",
    setPath: () => { },
});
