
import React, { useRef, useState } from "react";

import { KDSNavItemProps } from "external/page/nav/item/KDSNavItem.react";
import InternalKDSText from "internal/text/InternalKDSText.react";
import useKDSHover from "external/actions/useKDSHover";
import useKDSRouter from "external/router/useKDSRouter";
import InternalKDSLink from "internal/text/InternalKDSLink.react";
import useKDSTheme from "external/theme/useKDSTheme";
import { KDSMargin, KDSPadding } from "external/KDSEnums";
import KDSIcon from "external/icon/KDSIcon.react";
import InternalKDSHoverContent from "internal/layout/InternalKDSHoverContent.react";
import KDSText from "external/text/KDSText.react";
import KDSFlexLayout from "external/display/flex/KDSFlexLayout.react";
import KDSFlexItem from "external/display/flex/KDSFlexItem.react";
import KDSHoverable from "external/actions/KDSHoverable.react";


export default function InternalKDSAppbarNav({
    label,
    path,
    nav,
}: KDSNavItemProps): React.ReactElement {
    const [theme] = useKDSTheme();
    // TODO this should be shared by appbar and menu nav paths
    const labelToPath = (): string => {
        return label.toLowerCase().replace(/\s+/g, "-");
    };
    const url = path ?? labelToPath();
    const router = useKDSRouter();
    const isSelected = router.path.startsWith(
        url.startsWith("/") ? url : "/" + url
    );
    const container = useRef<HTMLDivElement>(null);
    const isHovered = useKDSHover(container);

    const navIcon = nav == null
        ? null
        : (
            <KDSIcon icon="keyboard_arrow_down" color="primary" size="small" />
        );

    const subNav = nav == null ? null : (
        <KDSFlexLayout direction="column"
            style={{
                padding: KDSPadding.vert_8,
            }}>
            {nav?.map((n, index) => <MenuItem key={index} {...n} />)}
        </KDSFlexLayout>
    );

    return (
        <InternalKDSHoverContent >
            <InternalKDSLink ref={container} to={url} style={{
            }}>
                <div style={{
                    padding: KDSPadding.vert_4_horiz_12,
                    borderRadius: '8px',
                    margin: KDSMargin.top_8,
                    boxShadow: isHovered && !isSelected
                        ? 'inset 0 4px 10px rgba(0, 0, 0, 0.2)'
                        : '',
                }}>
                    <InternalKDSText
                        size='large'
                        color={isSelected
                            ? theme.font.active
                            : theme.font.header}
                        style={{
                            display: "inline-block",
                            padding: KDSPadding.vert_4,
                            borderBottom: (
                                isSelected
                                    ? `2px solid ${theme.font.active}`
                                    : ''
                            ),
                        }}
                    >
                        {label}
                    </InternalKDSText>
                    {navIcon}
                </div>
            </InternalKDSLink>
            {subNav}
        </InternalKDSHoverContent >
    );
}



const MenuItem = (props: KDSNavItemProps): React.ReactElement => {
    const { label, tooltip } = props;
    const [isHovered, setIsHovered] = useState<boolean>(false);
    return (
        <KDSHoverable onHover={(hoverState) => setIsHovered(hoverState)}>
            <InternalKDSLink
                to={props.path ?? undefined}
                onClick={props.onClick ?? undefined}
                href={props.href ?? undefined}
                target="_blank"
                style={{
                    margin: KDSMargin.bot_4,
                    width: "100%",
                }}>
                <KDSFlexItem
                    style={{
                        borderRadius: "8px",
                        boxShadow: isHovered ? 'inset 0 4px 10px rgba(0, 0, 0, 0.2)' : undefined,
                        padding: KDSPadding.vert_8_horiz_24,
                        margin: KDSMargin.horiz_4
                    }}>
                    <KDSText width="100%" tooltip={tooltip}>{label}</KDSText>
                </KDSFlexItem>
            </InternalKDSLink>
        </KDSHoverable>
    );
}
