
import { KDSMargin } from "external/KDSEnums";
import React from "react";
import { KDSFlexProps } from "./KDSFlexLayout.react";

type Props = {
    children?: React.ReactNode,
    order?: number,
    grow?: number,
    shrink?: number,
    basis?: string,
    alignSelf?: "center" | "end" | "flex-end" | "flex-start" | "self-end" | "self-start" | "start" | "auto" | "stretch",
    margin?: KDSMargin,
    style?: {} // Temporary for debugging purposes only
} & KDSFlexProps;

export default function KDSFlexItem(
    { children,
        order,
        grow,
        shrink,
        basis,
        alignSelf,
        direction,
        justifyContent,
        alignItems,
        alignContent,
        height,
        width,
        backgroundColor,
        margin,

        style
    }: Props): React.ReactElement {
    return (
        <div style={
            {
                order,
                display: 'flex',
                flex: `${grow ?? 1} ${shrink ?? 1} ${basis ?? 0}`,
                alignSelf: alignSelf ?? 'stretch',
                flexDirection: direction,
                justifyContent,
                alignItems,
                alignContent,
                backgroundColor,
                margin,
                height,
                width,
                ...style,
            }}>{children}</div>
    );
}

