
import React from "react";

import KDSGridItem from "external/display/grid/KDSGridItem.react";
import KDSGridLayout from "external/display/grid/KDSGridLayout.react";
import { ClickProps } from "internal/button/InternalKDSButton.react";
import InternalKDSLink from "internal/text/InternalKDSLink.react";

type Props = {
    leftContent?: React.ReactNode | null,
    content: React.ReactNode,
    rightContent?: React.ReactNode | null,
} & ClickProps;

export default function InternalKDSLayout(props: Props): React.ReactElement {
    const { leftContent, content, rightContent } = props;
    const left = leftContent == null
        ? null
        : (
            <KDSGridItem
                gridArea="left"
                justifySelf="center"
                alignSelf="center">
                {leftContent}
            </KDSGridItem>
        );
    const right = rightContent == null
        ? null
        : (
            <KDSGridItem
                gridArea="right"
                justifySelf="center"
                alignSelf="center">
                {rightContent}
            </KDSGridItem>
        );
    const columns = `${left == null ? "" : "32px "}1fr${right == null ? "" : " 32px"}`;
    const areas =
        `
        '${left == null ? "" : "left "}content${right == null ? "" : " right"}'
        `;
    return (
        <InternalKDSLink {...props} >
            <KDSGridLayout
                gridTemplateRows="1fr"
                gridTemplateColumns={columns}
                gridTemplateAreas={areas}>
                {left}
                <KDSGridItem
                    gridArea="content">
                    {content}
                </KDSGridItem>
                {right}
            </KDSGridLayout>
        </InternalKDSLink>
    );
}

