
import React, { useContext } from "react";

import { AppContext } from "internal/app_context";
import KDSFlexLayout from "external/display/flex/KDSFlexLayout.react";
import KDSFlexItem from "external/display/flex/KDSFlexItem.react";
import { KDSMargin } from "external/KDSEnums";
import InternalKDSAppbarNav from "./InternalKDSAppbarNav.react";
import InternalKDSAppbarMenuIcon from "internal/page/nav/InternalKDSAppbarMenuIcon.react";
import InternalKDSAppbarAction from "internal/page/nav/InternalKDSAppbarAction.react";
import useKDSIsVisible from "external/display/useKDSIsVisible";
import useKDSResize from "external/actions/useKDSResize";

type Props = {
};

export default function InternalKDSAppbar({
}: Props): React.ReactElement {
    const { actions, icon, leftToRight, nav, theme } = useContext(AppContext);
    const [visibleRef, isVisible] = useKDSIsVisible<HTMLDivElement>();
    const [resizeRef, containerWidth] = useKDSResize<HTMLDivElement>();

    const fullView = isVisible && (containerWidth > 860);
    return (
        <KDSFlexLayout
            ref={resizeRef}
            // @ts-expect-error override exists for debug theme
            backgroundColor={theme.override?.appbar ?? theme.app?.primary}
            direction={leftToRight ? 'row' : 'row-reverse'}
            height="100%"
            width="100%"
            justifyContent="space-evenly"
        >
            <KDSFlexItem
                alignItems="center"
                grow={0}
                shrink={0}>
                {
                    fullView
                        ? <InternalKDSAppbarMenuIcon
                            to={"/"}
                            size="x-large"
                            config={icon} />
                        : <InternalKDSAppbarMenuIcon
                            onClick={() => {
                                // TODO Show menu
                            }}
                            size="default"
                            config={{
                                ...icon,
                                svg: undefined,
                                ico: undefined,
                                name: "menu"
                            }} />}
            </KDSFlexItem>
            <KDSFlexItem
                justifyContent="left"
                grow={1}
                style={{
                    // transition: "opacity 0.5s ease-in-out, visibility 0.5s ease-in-out", TODO figure out transitions and handle it gracefully with menu and icon
                    visibility: fullView ? undefined : "hidden"
                }}>
                {
                    nav.map((n) => {
                        if (typeof (n) == 'string') {
                            return (
                                <InternalKDSAppbarNav
                                    key={n}
                                    label={n} />
                            );
                        }
                        return (
                            <InternalKDSAppbarNav
                                key={n.label}
                                {...n} />
                        );
                    })
                }
            </KDSFlexItem>
            <KDSFlexItem
                grow={0}
                shrink={0}
                alignItems="center"
                justifyContent="right"
                margin={KDSMargin.horiz_8}
                style={{
                    // transition: "opacity 0.5s ease-in-out, visibility 0.5s ease-in-out",
                    visibility: fullView ? undefined : "hidden"
                }}>
                {
                    actions.map((a) =>
                        <InternalKDSAppbarAction
                            key={a.label}
                            {...a}
                        />)
                }
            </KDSFlexItem>
            <div ref={visibleRef} />
        </KDSFlexLayout >
    );
}
