
import { KDSElement } from "external/KDSTypes";
import React from "react";

type Props = {
    src: string,
    type?: "video/mp4"
} & KDSElement<HTMLVideoElement>;

export default function KDSVideo({
    src,
    type,

    ref,
    style
}: Props): React.ReactElement {
    return (
        <video ref={ref}
            loop={true}
            muted={true}
            preload="auto"
            autoPlay={true}
            src={src}
            style={{
                height: "auto",
                width: "100%",
                zIndex: 0,
                ...style
            }}>
            <source type={type ?? "video/mp4"} src={src} />
        </video>
    );
}
