// @flow

import { KDSAppLayout, KDSViewerLayout } from "external/KDSEnums";
import { useContext } from "react";
import { PageConfiguration, PageConfigurations } from "internal/page/KDSPageConfiguration";
import { AppContext } from "internal/app_context";

export default function usePageConfiguration(layout: KDSAppLayout): PageConfiguration {
    const { leftToRight } = useContext(AppContext);
    const configs = PageConfigurations[layout];
    return configs[leftToRight ? KDSViewerLayout.LEFT_TO_RIGHT : KDSViewerLayout.RIGHT_TO_LEFT];
}