
import { useEffect } from "react";

type Props = {
}
/*
https://fonts.google.com/icons?selected=Material+Icons
*/
export default function KDSGoogleFontLink({ }: Props): null {
    // TODO this should be a hook
    useEffect(() => {
        const iconLinks = [
            "https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined",
            "https://fonts.googleapis.com/css2?family=Material+Symbols+Rounded",
            "https://fonts.googleapis.com/css2?family=Material+Symbols+Sharp",
            "https://fonts.googleapis.com/css2?family=Roboto"
        ];

        const links = iconLinks.map((href) => {
            const link = document.createElement("link");
            link.href = href;
            link.rel = "stylesheet";
            document.head.appendChild(link);
            return link;
        });

        return () => {
            links.forEach((link) => document.head.removeChild(link)); // Cleanup if needed
        };
    }, []);
    return null;
}
