
import React, { CSSProperties } from "react";

import InternalKDSLink from "internal/text/InternalKDSLink.react";
import { KDSPadding } from "external/KDSEnums";
import KDSIcon from "external/icon/KDSIcon.react";
import { KDSAppIcon } from "internal/app_context";
import { ClickProps } from "internal/button/InternalKDSButton.react";

type Props = {
    config: KDSAppIcon,
    size: 'small' | 'default' | 'large' | 'x-large',
    style?: CSSProperties
} & ClickProps;

export default function InternalKDSAppbarMenuIcon(props: Props): React.ReactElement {
    const {
        config,
        size,
        style
    } = props;
    return (
        <InternalKDSLink {...props} style={{
            ...style,
            padding: KDSPadding.horiz_24,
        }}>
            <div
                style={{
                    ...style,
                    borderRadius: "12px",
                    overflow: "hidden",
                }}>
                <KDSIcon size={size} icon={config.name} {...config} />
            </div>
        </InternalKDSLink>
    );
}
