
import React, { RefObject } from "react";

import { KDSHeight, KDSWidth } from "external/KDSTypes";
import useKDSRouter from "external/router/useKDSRouter";
import { ClickProps } from "internal/button/InternalKDSButton.react";
import { KDSRef } from "external/actions/useKDSHover";

export type InternalKDSLinkProps<T extends HTMLElement> = {
    to?: string | undefined,
    children: React.ReactNode,
    height?: KDSHeight,
    width?: KDSWidth,
    ref?: KDSRef<T | HTMLAnchorElement>,
    style?: {},
} & ClickProps;

export default function InternalKDSLink<T extends HTMLElement>({
    to,
    href,
    target,
    onClick,
    children,
    height,
    width,
    ref,
    style
}: InternalKDSLinkProps<T>): React.ReactElement {
    const { goToRoute } = useKDSRouter();
    const onClickOrGoTo = () => {
        if (onClick) {
            onClick();
        }
        if (to) {
            goToRoute(to);
        }
    }
    return (
        <a

            ref={ref as RefObject<HTMLAnchorElement>}
            href={href}
            target={target}
            onClick={onClickOrGoTo}
            style={
                {
                    color: 'inherit',
                    display: 'inline-block',
                    textDecoration: "inherit",
                    cursor: "pointer",
                    height: height ?? "auto",
                    lineHeight: "1",
                    verticalAlign: "top",
                    width,
                    ...style
                }
            }>
            {children}
        </a>
    );
}

