
import React, { useContext } from "react";

import { AppContext } from "internal/app_context";
import { KDSAppLayout } from "external/KDSEnums";
import InternalKDSPageWithAppbar from "internal/page/InternalKDSPageWithAppbar.react";
import useKDSTheme from "external/theme/useKDSTheme";
import InternalKDSFooter from "internal/page/InternalKDSFooter.react";

type Props = {
    children?: React.ReactNode,
    appbar?: React.ReactNode,
    sidebar?: React.ReactNode,
    footer?: React.ReactNode
}
/*
Container for all content to show on a given Page. You should use a different
KDSPage component for each Page in your App.
The Page will setup the layout of your app.
ie: Header, Footer, Main content area, 
    and NavBar (Either as an appbar or sidebar depending on your App Configuration)
*/
export default function KDSPage(props: Props): React.ReactElement {
    const { layout } = useContext(AppContext);
    const [theme] = useKDSTheme();
    let content = null;
    switch (layout) {
        case (KDSAppLayout.APPBAR):
            content = <InternalKDSPageWithAppbar {...props} />
            break;
        default:
            throw new Error(`Layout ${layout} not implemented for KDSPage.`)
    }
    return (
        <div
            style={
                {
                    // @ts-expect-error override exists for debug theme
                    backgroundColor: theme.override?.page ?? theme.background,
                    position: "fixed",
                    top: 0,
                    bottom: 0,
                    left: 0,
                    right: 0,
                    height: "100%",
                    width: "100%",
                    overflow: "hidden",
                }}>
            {content}
            {props.footer ?? <InternalKDSFooter />}
        </div>
    );
}
