// @flow

import { KDSHeight, KDSWidth } from "external/KDSTypes";
import React from "react";

type Props = {
    children?: React.ReactNode, //React.ReactElement<typeof KDSFlexItem | ReadonlyArray<React.ReactElement<typeof KDSFlexItem>>>,
    gridTemplateRows?: "none" | "subgrid" | "auto" | "max-content" | "min-content" | (string & {}),
    gridTemplateColumns?: "none" | "subgrid" | "auto" | "max-content" | "min-content" | (string & {}),
    gridTemplateAreas?: "none" | (string & {}),
    columnGap?: "normal" | (string & {}),
    rowGap?: "normal" | (string & {}),
    justifyItems?: "center" | "end" | "start" | "baseline" | "stretch",
    alignItems?: "center" | "end" | "start" | "baseline" | "stretch",
    justifyContent?: "space-around" | "space-between" | "space-evenly" | "stretch" | "center" | "end" | "start",
    alignContent?: "space-around" | "space-between" | "space-evenly" | "stretch" | "center" | "end" | "start",
    gridAutoColumns?: "auto" | "max-content" | "min-content" | (string & {}),
    gridAutoRows?: "auto" | "max-content" | "min-content" | (string & {}),
    gridAutoFlow?: "column" | "dense" | "row",
    height?: KDSHeight,
    width?: KDSWidth,
    backgroundColor?: string,


    style?: {}, // TEMPORARY only for debugging
}

export default function KDSGridLayout(
    {
        children,
        gridTemplateRows,
        gridTemplateColumns,
        gridTemplateAreas,
        columnGap,
        rowGap,
        justifyItems,
        alignItems,
        justifyContent,
        alignContent,
        gridAutoColumns,
        gridAutoRows,
        gridAutoFlow,
        height,
        width,
        backgroundColor,

        style,
    }: Props): React.ReactElement {
    return (
        <div style={
            {
                display: "grid",
                gridTemplateRows,
                gridTemplateColumns,
                gridTemplateAreas,
                columnGap,
                rowGap,
                justifyItems,
                alignItems,
                justifyContent,
                alignContent,
                gridAutoColumns,
                gridAutoRows,
                gridAutoFlow,
                height,
                width,
                backgroundColor,
                overflow: 'hidden',
                ...style,
            }}>
            {children}
        </div>
    );
}

