
import React from "react";

import { KDSMargin } from "external/KDSEnums";
import { KDSHeight, KDSWidth } from "external/KDSTypes";
import { KDSRef } from "external/actions/useKDSHover";

type Props = {
    children?: React.ReactNode, //React.ReactElement<typeof KDSFlexItem | ReadonlyArray<React.ReactElement<typeof KDSFlexItem>>>,
} & KDSFlexProps;

export type KDSFlexProps = {
    basis?: 'auto' | 'content' | string, // % or px
    direction?: 'row' | 'row-reverse' | 'column' | 'column-reverse',
    justifyContent?: 'flex-start' | 'flex-end' | 'center' | 'space-between' | 'space-around' | 'space-evenly' | 'start' | 'end' | 'left' | 'right',
    alignItems?: 'stretch' | 'flex-start' | 'flex-end' | 'center' | 'baseline' | 'first baseline' | 'last baseline' | 'start' | 'end' | 'self-start' | 'self-end',
    alignContent?: 'flex-start' | 'flex-end' | 'center' | 'space-between' | 'space-around' | 'space-evenly' | 'stretch' | 'start' | 'end' | 'baseline' | 'first baseline' | 'last baseline',
    padding?: (string & {}),
    height?: KDSHeight,
    width?: KDSWidth,
    backgroundColor?: string,
    margin?: KDSMargin,
    overflow?: 'hidden' | 'auto',
    ref?: KDSRef<HTMLDivElement>,

    style?: {} // Temporary for debugging purposes only
}

export default function KDSFlexLayout(
    {
        alignItems,
        alignContent,
        backgroundColor,
        children,
        direction,
        height,
        justifyContent,
        margin,
        overflow,
        padding,
        ref,
        style,
        width,
    }: Props): React.ReactElement {
    return (
        <div
            ref={ref}
            style={
                {
                    alignItems,
                    alignContent,
                    backgroundColor,
                    display: "flex",
                    flex: 1,
                    flexDirection: direction,
                    height,
                    justifyContent,
                    margin,
                    overflow: overflow ?? 'hidden',
                    padding,
                    width,
                    ...style
                }}>
            {children}
        </div>
    );
}

