
import React, { useEffect, useState } from "react";
import { v4 } from "uuid";

import KDSGoogleFontLink from "external/icon/KDSGoogleFontLink.react";
import useKDSRouter, { KDSRoutes, RouterContext } from "external/router/useKDSRouter";
import KDSLightTheme from "external/theme/KDSLightTheme";
import { AppConfig, AppContext, KDSAppIcon } from "internal/app_context";
import { KDSState } from "external/KDSTypes";
import { KDSAppLayout } from "external/KDSEnums";
import KDSLoaderStatus from "external/loader/KDSLoaderStatus.react";
import { KDSNavItemProps } from "external/page/nav/item/KDSNavItem.react";
import { KDSTheme } from "external/theme/KDSTheme";
import RouteTrie from "./router/route_trie";
import { KDSActionItemProps } from "./page/nav/KDSActionItem.react";

type Props = {
    title: string;
    icon: KDSAppIcon;

    layout?: KDSAppLayout;
    leftToRight?: boolean;
    actions?: ReadonlyArray<KDSActionItemProps>,
    nav?: ReadonlyArray<KDSNavItemProps>,
    route?: KDSRoutes,
    sidebarIsCollapsed?: boolean;
    theme?: KDSTheme;
};

/*
Top level container that sets up AppContext.
This is a requirement for KDSComponents to work on your app.
You can access the component values with: 
    const config = useContext(AppContext);
*/
export default function KDSApp({
    actions,
    icon,
    layout,
    leftToRight,
    nav,
    route,
    sidebarIsCollapsed,
    title,
    theme,
}: Props): React.ReactElement {
    const [isLoading, setIsLoading] = useState<boolean>(
        !document.fonts.check("1em Material Icons")
    );
    const themeState = useState<KDSTheme>(theme ?? KDSLightTheme);
    const sidebarToggleState = useState<boolean>(sidebarIsCollapsed ?? false);
    const [path, setPath] = useState<string>("");
    _useAppSetup(themeState[0], title);

    useEffect(() => {
        document.fonts.ready.then(() => setIsLoading(false));

        const handlePopState = () => {
            setPath(window.location.pathname); // Update state when back is pressed
        };
        window.addEventListener("popstate", handlePopState);
        return () => {
            window.removeEventListener("popstate", handlePopState);
        };
    }, []);
    return (
        <div
            style={{
                width: "100%",
                height: "100%",
            }}
        >
            <KDSGoogleFontLink />
            <AppContext.Provider
                value={_setupAppConfig(
                    themeState,
                    sidebarToggleState,
                    title,
                    icon,
                    nav,
                    layout,
                    leftToRight,
                    actions
                )}
            >
                <RouterContext.Provider
                    value={{
                        base: "/",
                        path,
                        setPath,
                    }}
                >
                    {isLoading ? (
                        <div
                            style={{
                                display: "flex",
                                flexDirection: "column",
                                alignItems: "center",
                                justifyContent: "center",
                                position: "fixed",
                                top: "0",
                                left: "0",
                                width: "100vw",
                                height: "100vh",
                            }}
                        >
                            <KDSLoaderStatus />
                        </div>
                    ) : (
                        <RenderedPage routes={new RouteTrie(route)} />
                    )}
                </RouterContext.Provider>
            </AppContext.Provider>
        </div>
    );
}

const RenderedPage = (props: {
    routes: RouteTrie | null
}): React.ReactNode => {
    const { routes } = props;
    const { path } = useKDSRouter();
    return routes?.resolve(path);
}

const _useAppSetup = (theme: KDSTheme, title: string) => {
    useEffect(() => {
        document.title = title;
    }, [title]);
    useEffect(() => {
        // @ts-expect-error Fixes issue of scrolling and revelaing incorrect body color
        document.body.style = `background: ${theme.background}; color: ${theme.font.primary}; margin: 0px;`;
    }, [theme]);
};

const _setupAppConfig = (
    themeState: KDSState<KDSTheme>,
    sidebarToggleState: KDSState<boolean>,
    title: string,
    icon: KDSAppIcon,
    nav: ReadonlyArray<KDSNavItemProps> = [],
    layout: KDSAppLayout = KDSAppLayout.APPBAR,
    leftToRight: boolean = true,
    actions: ReadonlyArray<KDSActionItemProps> = [],
): AppConfig => {
    const [theme, setTheme] = themeState;
    const [sidebarIsCollapsed, sidebarToggle] = sidebarToggleState;
    return {
        actions,
        title,
        theme,
        setTheme,
        layout,
        leftToRight,
        icon,
        nav,
        sidebarIsCollapsed,
        sidebarToggle,
        session: v4().toUpperCase(),
    };
};
