
import React, { CSSProperties, useState } from "react";

import useKDSRouter from "external/router/useKDSRouter";
import useKDSTheme from "external/theme/useKDSTheme";
import KDSText from "external/text/KDSText.react";

export type ClickProps = {
    href?: undefined,
    target?: undefined,
    onClick: () => void,
    to?: undefined,
} |
{
    href: string,
    target?: '_blank' | '_self' | '_parent' | '_top',
    onClick?: undefined,
    to?: undefined,
} | {
    href?: undefined,
    target?: undefined,
    onClick?: undefined,
    to: string,
} | {
    href?: string | undefined,
    target?: '_blank' | '_self' | '_parent' | '_top' | undefined,
    onClick?: () => void | undefined,
    to: string | undefined,
};

type Props = {
    label: string,
    labelIsHidden?: boolean,
    disabled?: boolean,
    type?: 'button' | 'reset' | 'submit',
    use?: 'default' | 'flat',
    isCircular?: boolean,
    children?: React.ReactNode,
    textStyle?: CSSProperties,
    style?: CSSProperties
} & ClickProps;

export type KDSButtonProps = Props;

export default function InternalKDSButton(
    {
        disabled,
        label,
        labelIsHidden,
        type,
        use,
        onClick,
        children,
        href,
        target,
        isCircular,
        to,
        textStyle,
        style
    }: Props): React.ReactElement {
    const [theme] = useKDSTheme();
    const { goToRoute } = useKDSRouter();
    const [isPressed, setIsPressed] = useState<boolean>(false);
    const pickButtonColor = () => {
        const colorPicker = disabled
            ? theme.button.disabled
            : isPressed
                ? theme.button.pressed
                : use === 'flat'
                    ? null
                    : theme.button;
        return colorPicker == null
            ? 'transparent'
            : colorPicker[
            type === 'submit'
                ? 'primary'
                : type === 'reset'
                    ? 'negative'
                    : 'default'];
    };
    const onClickOrGoTo = () => {
        if (onClick) {
            onClick();
        }
        if (to) {
            goToRoute(to);
        }
    }
    const button = (
        <button
            aria-label={label}
            disabled={disabled}
            type={href != null ? 'submit' : type ?? "button"}
            onClick={disabled ? undefined : onClickOrGoTo}
            onMouseDown={() => setIsPressed(true)}
            onMouseUp={() => setIsPressed(false)}
            onMouseLeave={() => setIsPressed(false)}
            style={{
                borderRadius: isCircular ? "50%" : "20px",
                cursor: disabled ? "not-allowed" : "pointer",
                color: theme.font.primary,
                backgroundColor: pickButtonColor(),
                padding: isCircular ? undefined : '4px 8px 4px 8px',
                border: "none",
                userSelect: 'none',

                boxSizing: "content-box",
                fontWeight: "bold",
                minHeight: '20px',
                ...style
            }}
            formAction={href}
            formTarget={target ?? href == null ? undefined : "_blank"}
        >
            {children == null
                ? labelIsHidden
                    ? null
                    : <KDSText style={{ ...textStyle }}>{label}</KDSText>
                : children}
        </button>
    );
    return href == null
        ? button
        : (
            <form>
                {button}
            </form>
        );
}

