
import React, { useRef } from "react";
import useKDSHover from "external/actions/useKDSHover";
import { KDSElement } from "external/KDSTypes";

type Props = {
    children: React.ReactNode,
    onHover: (isHovered: boolean) => void
} & KDSElement<HTMLDivElement>;

export default function KDSHoverable({
    children,
    onHover,
    style,
}: Props): React.ReactElement {
    const ref = useRef<HTMLDivElement>(null);
    useKDSHover(ref, onHover);
    return (
        <div
            ref={ref}
            style={{
                ...style,
            }}>
            {children}
        </div>
    );
}

