import React, { useState } from "react";

import InternalKDSLayout from "internal/layout/InternalKDSLayout.react";
import KDSHoverable from "external/actions/KDSHoverable.react";
import InternalKDSText from "internal/text/InternalKDSText.react";
import useKDSRouter from "external/router/useKDSRouter";
import { KDSIconProps } from "external/icon/KDSIcon.react";

export type KDSNavItemProps = {
    label: string;
    path?: string;
    onClick?: () => void;
    href?: string,
    icon?: React.ReactNode | KDSIconProps | string;
    activeIcon?: React.ReactNode | KDSIconProps;
    isSelected?: boolean;
    nav?: ReadonlyArray<KDSNavItemProps>;
    tooltip?: string,
};

export default function KDSNavItem({
    label,
    path,
    // icon,
    // activeIcon,
}: KDSNavItemProps): React.ReactElement {
    const labelToPath = (): string => {
        return label.toLowerCase().replace(/\s+/g, "_");
    };
    const url = path ?? labelToPath();
    const router = useKDSRouter();
    const isSelected = router.path.startsWith(
        url.startsWith("/") ? url : "/" + url
    );
    const [isHovered, setIsHovered] = useState<boolean>(false);

    return (
        <div style={{ width: "auto" }}>
            <KDSHoverable onHover={(hoverState) => setIsHovered(hoverState)}>
                <InternalKDSLayout
                    to={url}
                    content={
                        <div
                            style={{
                                backgroundColor: "black",
                                position: "absolute",
                                overflow: "visible",
                            }}
                        >
                            <InternalKDSText
                                size="large"
                                weight={"bold"}
                                color={isSelected || isHovered
                                    ? "rgb(0, 0, 100, .5)"
                                    : ""}
                                boxShadow={
                                    isSelected || isHovered
                                        ? "-12px 24px 8px rgb(0, 0, 100, .5), 12px 24px 8px rgb(0, 0, 100, .5)"
                                        : ""
                                }
                                textDecorationThickness={
                                    isSelected || isHovered
                                        ? ""
                                        : ""
                                }
                            >
                                {label}
                            </InternalKDSText>
                        </div>
                    }
                // leftContent={isSelected ? activeIcon ?? icon : icon}
                />
            </KDSHoverable>
        </div>
    );
}
