
import React from "react";
import { Properties } from "csstype";

import useKDSTheme from "external/theme/useKDSTheme";

export type InternalKDSTextProps = {
    size?: "xx-small" | "x-small" | "small" | "medium" | "large" | "x-large" | "xx-large" | "xx-large" | "smaller" | "larger",
    weight?: "normal" | "bold" | "lighter" | "bolder",
    selectable?: boolean,
    children: React.ReactNode,
    style?: {},
    tooltip?: string
} & Properties;

export default function InternalKDSText(props: InternalKDSTextProps): React.ReactElement {
    const {
        size,
        weight,
        selectable,
        children,
        style,
        tooltip,
    } = props;
    const [theme] = useKDSTheme();
    return (
        <p
            title={tooltip}
            style={{
                fontFamily: "BlinkMacSystemFont, Roboto",  // TODO allow this to be configured
                fontSize: size ?? 'medium',
                fontWeight: weight ?? 'normal',
                color: theme.font.primary,
                userSelect: selectable ? 'text' : 'none',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
                margin: 0,
                ...props,
                ...style,
            }}
        >{children}</p>
    );
}

