
import React from "react";

import { KDSAppLayout } from "external/KDSEnums";
import usePageConfiguration from "internal/page/usePageConfiguration";
import useKDSTheme from "external/theme/useKDSTheme";
import KDSGrid from "external/display/grid/KDSGridLayout.react"
import KDSGridItem from "external/display/grid/KDSGridItem.react";
import InternalKDSAppbar from "internal/page/nav/InternalKDSAppbar.react";

type Props = {
    appbar?: React.ReactNode,
    children?: React.ReactNode
};

export default function InternalKDSPageWithAppbar({
    appbar,
    children
}: Props): React.ReactElement {
    const [theme] = useKDSTheme();
    const page_config = usePageConfiguration(KDSAppLayout.APPBAR);
    return (
        <KDSGrid
            gridTemplateRows={page_config.rows}
            gridTemplateColumns={page_config.columns}
            gridTemplateAreas={page_config.areas}
            style={{
                width: "100%",
                height: "100%",
            }}>
            <KDSGridItem gridArea="appbar" style={{
                boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.2)",
                position: "relative"
            }}>
                {appbar ?? <InternalKDSAppbar />}
            </KDSGridItem>
            <KDSGridItem gridArea="main" style={
                {
                    // @ts-expect-error override exists for debug theme
                    backgroundColor: theme.override?.main,
                    height: "100%",
                    width: "100%",
                    overflow: "auto",
                }
            }>
                {children}
            </KDSGridItem>
        </KDSGrid>
    );
}
